+  'blocked': 'required-checks-pending',
+  'has_hooks': 'has-hooks',
+  'draft': 'draft',
+  'unstable': 'unstable',
+};
+
+/// GitHub merge-state tokens that map straight to a state (no reason).
+const _ghSimpleStates = {
+  'clean': stateClean,
+  'dirty': stateDirty,
+  'behind': stateBehind,
+};
