+    final conclusion = map?['conclusion'] as String?;
+    verdicts.add(
+      conclusion == null
+          ? _statusVerdict(map?['status'] as String?)
+          : ghConclusionVerdict(conclusion),
+    );
+  }
+  return _rollupVerdicts(verdicts);
