+    test('empty rollup is none — no evidence at all', () {
+      expect(ghCheckRunsVerdict(const []), 'none');
+    });
+
+    test('any failure is fail (multi-item case)', () {
+      final v = ghCheckRunsVerdict([
+        {'conclusion': 'success'},
+        {'conclusion': 'failure'},
+      ]);
+      expect(v, 'fail');
+    });
