+      // The full GL status alphabet (11 pipeline + commit statuses) —
+      // nothing may fall through as a crash or a silent pass.
+      for (final s in const [
+        'created',
+        'waiting_for_resource',
+        'preparing',
+        'pending',
+        'running',
+        'scheduled',
+        'canceled',
+        'canceled_by_caller',
+        'skipped',
+        'manual',
