+      h['scm_remove_label']!({...repo, 'pr': 5, 'label': 'ai_validating'});
+      h['scm_add_pr_comment']!({...repo, 'pr': 5, 'text': 'note'});
+      h['scm_get_pr_comments']!({...repo, 'pr': 5});
